draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // baby
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // steps
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 70);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t) - 10, H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 70);
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t) + 10, H/2 + 90);
  ctx.stroke();

  ctx.restore();
}
